// The Webhook node wraps the incoming payload in a 'body' object
const payload = $input.first().json.body;

// Safely extract the metadata
const tenantId = payload?.data?.object?.metadata?.tenant_id;
const eventId = payload?.id;

if (!tenantId) {
  throw new Error("No tenant_id found in payload metadata");
}

return [{
  json: {
    tenant_id: tenantId,
    stripe_event_id: eventId,
    raw_payload: payload
  }
}];

// Get the tenant configuration from the Postgres node
const tenant = $json;
const rawPayload = $('Extract Tenant ID').first().json.raw_payload;
const paymentIntentId = rawPayload?.data?.object?.id;

if (!paymentIntentId) {
  throw new Error("No payment intent ID found in payload");
}

// Fetch the latest payment details using the tenant's specific Stripe key
const stripeResponse = await this.helpers.httpRequest({
  method: 'GET',
  url: `https://api.stripe.com/v1/payment_intents/${paymentIntentId}`,
  headers: {
    'Authorization': `Bearer ${tenant.stripe_api_key}`
  }
});

return [{
  json: {
    tenant_id: tenant.tenant_id,
    company_name: tenant.company_name,
    slack_webhook_url: tenant.slack_webhook_url,
    slack_channel: tenant.slack_channel,
    payment_data: stripeResponse,
    stripe_event_id: $('Extract Tenant ID').first().json.stripe_event_id
  }
}];

const data = $input.first().json;
const amount = (data.payment_data.amount / 100).toFixed(2);
const currency = data.payment_data.currency.toUpperCase();
const email = data.payment_data.receipt_email || 'Unknown';

const text = `ðŸ’³ *Payment Received for ${data.company_name}*\nâ€¢ Amount: ${currency} ${amount}\nâ€¢ Customer: ${email}\nâ€¢ Tenant ID: ${data.tenant_id}`;

return [{
  json: {
    ...data,
    slack_text: text
  }
}];

const data = $input.first().json;
let slackStatus = 'failed'; // Default to failed
let slackError = null;

try {
  // Dynamically send to the tenant's specific Slack webhook
  const response = await this.helpers.httpRequest({
    method: 'POST',
    url: data.slack_webhook_url,
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ text: data.slack_text })
  });

  // Strict check: Slack only returns "ok" or {ok: true} on success.
  if (response === 'ok' || (response && response.ok === true)) {
    slackStatus = 'success';
  } else {
    // If it didn't return "ok", we treat it as a failure and capture what it did return.
    slackStatus = 'failed';
    slackError = `Unexpected Slack response: ${JSON.stringify(response).substring(0, 100)}`;
  }
} catch (error) {
  slackStatus = 'failed';
  slackError = error.message;
}

return [{
  json: {
    tenant_id: data.tenant_id,
    stripe_event_id: data.stripe_event_id,
    payment_intent_id: data.payment_data.id,
    amount_cents: data.payment_data.amount,
    currency: data.payment_data.currency,
    slack_status: slackStatus,
    slack_error: slackError
  }
}];
